var client = new OpenAIClient(new Uri("https://my-openai.openai.azure.com/"), new AzureKeyCredential(Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")));

var chatCompletions = new ChatCompletions(
    deploymentName: "gpt-4",
    messages: new[]
    {
        new ChatMessage(ChatRole.System, "You are a helpful assistant."),
        new ChatMessage(ChatRole.User, "Summarize this article: ...")
    },
    temperature: 0.7f
);

var result = await client.GetChatCompletionsAsync(chatCompletions);
string summary = result.Value.Choices[0].Message.Content;

var client = new TextAnalyticsClient(new Uri("https://my-text-analytics.cognitiveservices.azure.com/"), new AzureKeyCredential(Environment.GetEnvironmentVariable("TEXT_ANALYTICS_KEY")));

var sentiment = await client.AnalyzeSentimentAsync("I love this product!");
Console.WriteLine($"Sentiment: {sentiment.Value.Sentiment}");
Console.WriteLine($"Confidence: {sentiment.Value.ConfidenceScores.Positive}");
